def tooltip_for(tab: str, label: str) -> str:
    """Curated hover text for a field label/caption on `tab`, or "" if none."""
    return FIELD_HELP.get(tab, {}).get((label or '').strip(), '')


def section_tooltip(tab: str, title: str) -> str:
    """Curated hover text for a section panel title on `tab`, or "" if none."""
    return SECTION_HELP.get(tab, {}).get((title or '').strip(), '')
